// Put your Meta App ID here. It tells your own bot's replies apart from
// a teammate replying by hand in the Page inbox.
const APP_ID = '926883426543798';

const out = [];

for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const entries = Array.isArray(body.entry) ? body.entry : [];

  for (const entry of entries) {
    const pageId = entry.id;
    const events = Array.isArray(entry.messaging) ? entry.messaging : [];

    for (const ev of events) {
      const msg = ev.message || {};

      // An echo is a message the Page sent out
      if (msg.is_echo === true) {
        // Sent by our own bot, ignore it
        if (String(msg.app_id || '') === String(APP_ID)) continue;

        // Sent by a human on the team. In an echo the customer is the recipient.
        const customerId = ev.recipient && ev.recipient.id;
        if (!customerId) continue;

        out.push({
          json: {
            type: 'human_reply',
            sender_id: customerId,
            page_id: pageId,
            message: msg.text || '',
            timestamp: ev.timestamp || Date.now(),
          },
        });
        continue;
      }

      const senderId = ev.sender && ev.sender.id;
      if (!senderId) continue;
      if (senderId === pageId) continue;
      if (!msg.mid) continue;

      const text = (msg.text || '').trim();
      if (!text) continue;

      out.push({
        json: {
          type: 'customer',
          message_id: msg.mid,
          sender_id: senderId,
          page_id: pageId,
          message: text,
          timestamp: ev.timestamp || Date.now(),
        },
      });
    }
  }
}

return out;

// Inside the loop, .first() on the loop node is the message being handled now.
const msg = $('Loop Over Messages').first().json;

const history = $input.all()
  .map(i => i.json)
  .filter(j => j && j.fields)
  .map(j => ({
    message: j.fields['Message'] || '',
    reply: j.fields['Reply Sent'] || '',
    intent: j.fields['Intent'] || '',
  }))
  .reverse();

return [{
  json: {
    message_id: msg.message_id,
    sender_id: msg.sender_id,
    page_id: msg.page_id,
    message: msg.message,
    timestamp: msg.timestamp,
    history,
  },
}];

