const ctx = $('Build Context').first().json;

let aiOut;
try {
  aiOut = $('Classify and Draft').first().json.output;
} catch (e) {
  aiOut = null;
}

let parsed = null;
try {
  let raw = typeof aiOut === 'string' ? aiOut : JSON.stringify(aiOut);
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start !== -1 && end !== -1) raw = raw.slice(start, end + 1);
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

// A broken answer must never become a guess sent to a customer
if (!parsed || typeof parsed !== 'object') {
  parsed = {
    intent: 'other',
    confidence: 0,
    needs_human: true,
    reply: '',
    reason: 'Could not read the AI output',
  };
}

const allowed = ['greeting', 'human_request', 'pricing', 'service_info', 'demo_request', 'timeline', 'support', 'complaint', 'spam', 'other'];
let intent = allowed.includes(parsed.intent) ? parsed.intent : 'other';

let conf = Number(parsed.confidence);
if (!isFinite(conf) || conf < 0 || conf > 1) conf = 0;

let reply = typeof parsed.reply === 'string' ? parsed.reply.trim() : '';

const text = (ctx.message || '').toLowerCase().trim();

// Safety net 1: never let a plain greeting be dropped as spam
const greetingWords = ['hi', 'hello', 'hey', 'helo', 'hii', 'good morning', 'good afternoon',
  'good evening', 'kumusta', 'kamusta', 'musta', 'hola', 'yo', 'sup', 'good day', 'hi po', 'hello po'];
const stripped = text.replace(/[^a-z\s]/g, '').trim();
const looksLikeGreeting = greetingWords.includes(stripped) || (stripped.split(/\s+/).length <= 3 && greetingWords.some(g => stripped.startsWith(g)));

if (looksLikeGreeting && intent === 'spam') {
  intent = 'greeting';
  conf = 0.9;
}

// Safety net 1b: someone asking for Rey or a human always reaches a human
const humanWords = ['talk to rey', 'speak to rey', 'is rey', 'rey there', 'reach rey',
  'real person', 'talk to a human', 'talk to someone', 'speak to someone', 'speak to a human',
  'are you a bot', 'is this a bot', 'am i talking to a bot', 'is this ai', 'are you ai',
  'human please', 'agent please', 'customer service', 'tao ba', 'totoong tao'];
if (humanWords.some(w => text.includes(w))) {
  intent = 'human_request';
  conf = Math.max(conf, 0.9);
}

// Safety net 2: spam needs real certainty, otherwise treat it as a person
if (intent === 'spam' && conf < 0.9) {
  intent = 'other';
}

// Safety net 3: a greeting always gets something back
if (intent === 'greeting' && reply === '') {
  reply = 'Hi, thanks for messaging. What part of your work are you hoping to automate?';
  conf = Math.max(conf, 0.8);
}

// Hard rules win over whatever the model decided about itself
const needsHuman = intent === 'greeting'
  ? false
  : intent === 'human_request'
  ? true
  : (parsed.needs_human === true
     || conf < 0.7
     || ['pricing', 'demo_request', 'timeline', 'complaint'].includes(intent)
     || reply === '');

// What the customer hears while they wait for a human
const holdingByIntent = {
  human_request: 'Yes, Rey handles these himself. He will reply here shortly. In the meantime, feel free to tell me what you are hoping to automate so he has some context.',
  pricing: 'Thanks for asking. Pricing depends on what you need built, so Rey will message you himself with a real number. Usually within a few hours.',
  demo_request: 'Happy to show you. Rey will reach out shortly to set up a quick call and walk you through a live build.',
  timeline: 'Good question. Timing depends on the setup, so Rey will get back to you with a straight answer shortly.',
  complaint: 'Sorry about that. A real person is reading this now and will get back to you shortly.',
  support: 'Thanks for flagging this. Rey will take a look and get back to you shortly.',
};
const holding = holdingByIntent[intent] || 'Thanks for reaching out. Rey will get back to you personally shortly.';

// Only confirmed spam gets silence
const sendHolding = needsHuman;

return [{
  json: {
    message_id: ctx.message_id,
    sender_id: ctx.sender_id,
    page_id: ctx.page_id,
    message: ctx.message,
    timestamp: ctx.timestamp,
    intent,
    confidence: conf,
    needs_human: needsHuman,
    reply,
    holding,
    send_holding: sendHolding,
    reason: typeof parsed.reason === 'string' ? parsed.reason : '',
  },
}];

