// ---------- settings ----------
const PAUSE_HOURS = 6;          // how long the bot stays quiet after a human replies
const OFFICE_HOURS_ONLY = false; // true = bot only answers when the team is offline
const TZ_OFFSET = 8;            // Philippines is UTC+8
const OFFICE_START = 9;         // 9am
const OFFICE_END = 18;          // 6pm
// ------------------------------

const msg = $('Loop Over Messages').first().json;

const rows = $input.all().map(i => i.json).filter(j => j && j.fields);
let pausedUntil = 0;
if (rows.length && rows[0].fields['Paused Until']) {
  pausedUntil = new Date(rows[0].fields['Paused Until']).getTime();
}

const humanActive = pausedUntil > Date.now();

const local = new Date(Date.now() + TZ_OFFSET * 3600 * 1000);
const hour = local.getUTCHours();
const day = local.getUTCDay();
const inOffice = day >= 1 && day <= 5 && hour >= OFFICE_START && hour < OFFICE_END;

const botAllowed = !humanActive && (!OFFICE_HOURS_ONLY || !inOffice);

return [{
  json: {
    ...msg,
    bot_allowed: botAllowed,
    human_active: humanActive,
    in_office: inOffice,
    paused_until: pausedUntil ? new Date(pausedUntil).toISOString() : '',
  },
}];
